      const owner = actionOwner;
      eng.runner.cancel("视觉设置变更", { module: "visual" });
      await eng.repo.mutate(s => { (s.visual ||= avsFresh())[key] = next; }, { guard: () => eng.bridge.owner() === owner, label: "更新视觉偏好" });
